public class Methods {
    static int add(int a, int b)          { return a + b; }
    static double add(double a, double b) { return a + b; }       // overload
    static int add(int a, int b, int c)   { return a + b + c; }   // overload

    static void increment(int n) { n = n + 1; }                   // copy only
    static void fill(int[] arr)  { arr[0] = 99; }                 // changes the real array

    static boolean isPalindrome(String s) {
        String rev = "";
        for (int i = s.length() - 1; i >= 0; i--) rev += s.charAt(i);
        return s.equals(rev);
    }
    static int factorial(int n) {
        if (n <= 1) return 1;            // base case
        return n * factorial(n - 1);
    }
    public static void main(String[] args) {
        int v = 5; increment(v);
        System.out.println(v);                          // 5
        int[] a = {1, 2}; fill(a);
        System.out.println(a[0]);                       // 99
        System.out.println(add(2, 3) + " " + add(2.5, 1.5)); // 5 4.0
        System.out.println(isPalindrome("mum"));        // true
        System.out.println(factorial(5));               // 120
    }
}

